/*
 * lazyshell config editor — site/en/config-editor.html, site/fr/editeur-config.html.
 *
 * Entirely client-side, no build step, matching every other asset under
 * site/assets/ (see styles.css's own header comment): fetches
 * config-schema.json (generated by cmd/gen-config-schema from pkg/config's
 * structs — see ROADMAP.md's "Éditeur de configuration graphique sur le
 * site statique"), renders one form per tab (user config / project
 * lazyshell.yml), and keeps a read-only YAML preview in sync as the form
 * changes. A pasted YAML file can also populate the form back — see
 * parseYAML/applyParsed.
 *
 * This is a documentation aid, not a file editor: nothing here ever touches
 * the filesystem lazyshell itself reads from. The only artifact that
 * matters is the YAML text on the right, meant to be copied into a real
 * config.yml or lazyshell.yml by hand.
 */
(function () {
  "use strict";

  // CHROME only covers strings for elements this file builds itself with no
  // static HTML equivalent (list add/remove buttons, the warnings box, the
  // "not declared" tri-state option). Everything else — headings, lede,
  // tab labels, the Copy/Apply buttons' initial label — is hand-written per
  // language directly in config-editor.html/editeur-config.html, the same
  // "duplicate by hand, each page in its own language" convention every
  // other page on this site already follows.
  const CHROME = {
    en: {
      add: "Add",
      remove: "Remove",
      copied: "Copied",
      warningsTitle: "Ignored while loading:",
      loadError: "Could not load config-schema.json.",
      notMapping: "the pasted text is not a YAML mapping at the top level — nothing was loaded.",
      key: "key",
      value: "value",
      notDeclared: "(not declared)",
      byDefault: "(default)",
    },
    fr: {
      add: "Ajouter",
      remove: "Retirer",
      copied: "Copié",
      warningsTitle: "Ignoré au chargement :",
      loadError: "Impossible de charger config-schema.json.",
      notMapping: "le texte collé n'est pas une correspondance YAML de premier niveau — rien n'a été chargé.",
      key: "clé",
      value: "valeur",
      notDeclared: "(non déclaré)",
      byDefault: "(par défaut)",
    },
  };

  const lang = (document.documentElement.lang || "en").startsWith("fr") ? "fr" : "en";
  const t = (key) => CHROME[lang][key] || CHROME.en[key] || key;

  document.addEventListener("DOMContentLoaded", init);

  function init() {
    fetch("../assets/config-schema.json")
      .then((r) => {
        if (!r.ok) throw new Error(String(r.status));
        return r.json();
      })
      .then((schema) => boot(schema))
      .catch(() => {
        const root = document.getElementById("config-editor-root");
        if (root) root.textContent = t("loadError");
      });
  }

  // ---------- tree building ----------
  //
  // Both tabs are rendered, serialized and parsed by the same recursive
  // code, walking a tree of nodes with a `.children` map keyed by the local
  // property name at that level. Config's schema is a flat, dotted list
  // (see cmd/gen-config-schema's buildConfigFields) and gets grouped into a
  // tree here; ProjectConfig's schema already arrives as a tree
  // (itemFields), so buildProjectTree only has to convert it to the same
  // `.children` shape.

  function buildConfigTree(fields) {
    const root = { key: null, type: "root", children: {} };

    for (const f of fields) {
      const parts = f.key.split(".");

      if (parts.length === 1) {
        root.children[parts[0]] = f;

        continue;
      }

      const groupName = parts[0];
      let group = root.children[groupName];
      if (!group) {
        group = { key: groupName, type: "group", children: {} };
        root.children[groupName] = group;
      }

      group.children[parts.slice(1).join(".")] = f;
    }

    return root;
  }

  function buildProjectTree(fields) {
    const root = { key: null, type: "root", children: {} };

    for (const f of fields) {
      root.children[f.key] = f;
      attachChildren(f);
    }

    return root;
  }

  // attachChildren turns a list-of-struct field's itemFields into the same
  // `.children` map every other node carries, keyed by each child's name
  // relative to one list entry — "sessions[].watch[].pattern" becomes
  // "pattern" once its parent is "sessions[].watch". Recurses, so a list
  // nested inside a list entry (sessions[].watch) gets the same treatment.
  function attachChildren(node) {
    if (node.type !== "list" || node.itemType !== "struct" || !node.itemFields) return;

    node.children = {};

    const prefix = node.key + "[].";

    for (const child of node.itemFields) {
      const name = child.key.startsWith(prefix) ? child.key.slice(prefix.length) : child.key;

      node.children[name] = child;
      attachChildren(child);
    }
  }

  // ---------- boot ----------

  function boot(schema) {
    const configTree = buildConfigTree(schema.config);
    const projectTree = buildProjectTree(schema.project);

    const tabs = {
      config: { tree: configTree, state: {}, isConfig: true },
      project: { tree: projectTree, state: {}, isConfig: false },
    };

    setupColorList("config", schema.colorNames);
    setupColorList("project", schema.colorNames);

    for (const tabName of Object.keys(tabs)) {
      const tab = tabs[tabName];
      tab.rebuild = () => {
        rebuildForm(tabName, tab);
        updateYAML(tabName, tab);
      };
      tab.update = () => updateYAML(tabName, tab);
      tab.rebuild();

      wireCopy(tabName);
      wireApply(tabName, tab);
    }

    wireTabs();
  }

  function setupColorList(tabName, colorNames) {
    const list = document.getElementById("colorlist-" + tabName);
    if (!list || !colorNames) return;

    for (const name of colorNames) {
      const opt = document.createElement("option");
      opt.value = name;
      list.appendChild(opt);
    }
  }

  function wireTabs() {
    const buttons = document.querySelectorAll(".cfg-tab");
    buttons.forEach((btn) => {
      btn.addEventListener("click", () => {
        buttons.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");

        document.querySelectorAll(".cfg-panel").forEach((p) => {
          p.hidden = p.getAttribute("data-panel") !== btn.getAttribute("data-tab");
        });
      });
    });
  }

  // ---------- form rendering ----------

  function rebuildForm(tabName, tab) {
    const mount = document.getElementById("form-" + tabName);
    if (!mount) return;

    mount.textContent = "";
    renderChildren(tab.tree, mount, tab.state, tab);
  }

  function renderChildren(node, container, state, tab) {
    for (const prop in node.children) {
      renderNode(node.children[prop], prop, container, state, tab);
    }
  }

  function renderNode(field, prop, container, state, tab) {
    switch (field.type) {
      case "group":
        renderGroup(field, prop, container, state, tab);
        break;
      case "list":
        renderList(field, prop, container, state, tab);
        break;
      case "map":
        renderMap(field, prop, container, state, tab);
        break;
      default:
        renderScalar(field, prop, container, state, tab);
    }
  }

  function renderGroup(field, prop, container, state, tab) {
    if (!state[prop]) state[prop] = {};

    const fs = el("fieldset", "cfg-group");
    fs.appendChild(el("legend", "cfg-group-legend", humanLabel(prop)));

    renderChildren(field, fs, state[prop], tab);

    container.appendChild(fs);
  }

  function renderScalar(field, prop, container, state, tab) {
    const wrap = el("div", "cfg-field");

    const head = el("div", "cfg-field-head");
    head.appendChild(el("code", null, prop));
    wrap.appendChild(head);

    const input = buildScalarInput(field, prop, state, tab);
    wrap.appendChild(input);

    const help = field["help_" + lang] || field.help_en;
    if (help) wrap.appendChild(el("p", "cfg-help", stripInlineMarkup(help)));

    if (!tab.isConfig) {
      const def = field["defaultText_" + lang] || field.defaultText_en;
      if (def) wrap.appendChild(el("p", "cfg-default", "→ " + stripInlineMarkup(def)));
    }

    container.appendChild(wrap);
  }

  function buildScalarInput(field, prop, state, tab) {
    if (field.nilable) return buildNilableBoolInput(field, prop, state, tab);

    switch (field.type) {
      case "bool":
        return buildBoolInput(field, prop, state, tab);
      case "enum":
        return buildEnumInput(field, prop, state, tab);
      case "int":
        return buildIntInput(field, prop, state, tab);
      case "color":
        return buildTextInput(field, prop, state, tab, "colorlist-" + currentTab(tab));
      default:
        return buildTextInput(field, prop, state, tab, null);
    }
  }

  // currentTab has no direct handle on the tab name from inside a field
  // builder, so it is recovered from which datalist actually exists — both
  // tabs' datalists are always present, one per tab, and a color field only
  // ever renders inside its own tab's form.
  function currentTab(tab) {
    return tab.isConfig ? "config" : "project";
  }

  function buildTextInput(field, prop, state, tab, datalistId) {
    const input = document.createElement("input");
    input.type = "text";
    if (datalistId) input.setAttribute("list", datalistId);

    if (tab.isConfig) {
      if (state[prop] === undefined) state[prop] = field.default !== undefined ? field.default : "";
      input.value = state[prop];
    } else {
      input.value = state[prop] !== undefined ? state[prop] : "";
      const ph = field["defaultText_" + lang] || field.defaultText_en;
      if (ph) input.placeholder = ph.replace(/`/g, "");
    }

    input.addEventListener("input", () => {
      state[prop] = input.value;
      tab.update();
    });

    return input;
  }

  function buildIntInput(field, prop, state, tab) {
    const input = document.createElement("input");
    input.type = "number";
    if (field.min !== null && field.min !== undefined) input.min = String(field.min);
    if (field.max !== null && field.max !== undefined) input.max = String(field.max);

    if (tab.isConfig) {
      if (state[prop] === undefined) state[prop] = field.default !== undefined ? field.default : 0;
      input.value = String(state[prop]);
    } else {
      input.value = state[prop] !== undefined ? String(state[prop]) : "";
    }

    input.addEventListener("input", () => {
      const n = parseInt(input.value, 10);
      state[prop] = Number.isNaN(n) ? (tab.isConfig ? field.default : undefined) : n;
      tab.update();
    });

    return input;
  }

  function buildBoolInput(field, prop, state, tab) {
    const input = document.createElement("input");
    input.type = "checkbox";

    if (tab.isConfig) {
      if (state[prop] === undefined) state[prop] = !!field.default;
      input.checked = !!state[prop];
    } else {
      input.checked = !!state[prop];
    }

    input.addEventListener("change", () => {
      state[prop] = input.checked;
      tab.update();
    });

    return input;
  }

  // buildNilableBoolInput renders a three-state choice — "not declared" is
  // a real, distinct state for a *bool project field (see SessionSpec's
  // NoDefaultEnv/Locked), not just an alias for false.
  function buildNilableBoolInput(field, prop, state, tab) {
    const select = document.createElement("select");

    const unset = document.createElement("option");
    unset.value = "";
    unset.textContent = t("notDeclared");
    select.appendChild(unset);

    for (const v of ["true", "false"]) {
      const opt = document.createElement("option");
      opt.value = v;
      opt.textContent = v;
      select.appendChild(opt);
    }

    select.value = state[prop] === true ? "true" : state[prop] === false ? "false" : "";

    select.addEventListener("change", () => {
      state[prop] = select.value === "" ? undefined : select.value === "true";
      tab.update();
    });

    return select;
  }

  function buildEnumInput(field, prop, state, tab) {
    const select = document.createElement("select");

    const values = field.enum || [];
    const hasDefault = tab.isConfig && field.default !== undefined;

    if (!hasDefault) {
      const blank = document.createElement("option");
      blank.value = "";
      blank.textContent = t("byDefault");
      select.appendChild(blank);
    }

    for (const v of values) {
      const opt = document.createElement("option");
      opt.value = v;
      opt.textContent = v;
      select.appendChild(opt);
    }

    if (tab.isConfig && state[prop] === undefined) state[prop] = field.default;
    select.value = state[prop] !== undefined ? state[prop] : "";

    select.addEventListener("change", () => {
      state[prop] = select.value === "" ? (tab.isConfig ? field.default : undefined) : select.value;
      tab.update();
    });

    return select;
  }

  // renderList handles both a scalar list (env_files: [] of string) and a
  // list of structs (sessions, groups, sessions[].watch) — the two only
  // differ in how one row's editor is built.
  function renderList(field, prop, container, state, tab) {
    const wrap = el("div", "cfg-field cfg-list");
    wrap.appendChild(el("div", "cfg-field-head", el("code", null, prop)));

    const help = field["help_" + lang] || field.help_en;
    if (help) wrap.appendChild(el("p", "cfg-help", stripInlineMarkup(help)));

    if (!Array.isArray(state[prop])) state[prop] = [];
    const items = state[prop];

    const rows = el("div", "cfg-list-rows");
    wrap.appendChild(rows);

    for (let i = 0; i < items.length; i++) {
      rows.appendChild(renderListRow(field, items, i, tab));
    }

    const addBtn = el("button", "btn cfg-add", "+ " + t("add"));
    addBtn.type = "button";
    addBtn.addEventListener("click", () => {
      items.push(field.itemType === "struct" ? {} : "");
      tab.rebuild();
    });
    wrap.appendChild(addBtn);

    container.appendChild(wrap);
  }

  function renderListRow(field, items, index, tab) {
    const row = el("div", "cfg-list-row");

    if (field.itemType === "struct") {
      const fs = el("fieldset", "cfg-item");
      const label = itemLabel(field, items[index], index);
      const legend = el("legend", null, label);
      fs.appendChild(legend);

      if (!items[index]) items[index] = {};
      renderChildren(field, fs, items[index], tab);

      row.appendChild(fs);
    } else {
      const input = document.createElement("input");
      input.type = "text";
      input.value = items[index] || "";
      input.addEventListener("input", () => {
        items[index] = input.value;
        tab.update();
      });
      row.appendChild(input);
    }

    const removeBtn = el("button", "btn cfg-remove", "✕ " + t("remove"));
    removeBtn.type = "button";
    removeBtn.addEventListener("click", () => {
      items.splice(index, 1);
      tab.rebuild();
    });
    row.appendChild(removeBtn);

    return row;
  }

  // itemLabel shows a list-of-struct entry's own "name" field live, when it
  // has one (sessions, groups) — otherwise falls back to a 1-based index
  // (sessions[].watch entries have no name).
  function itemLabel(field, item, index) {
    if (item && typeof item.name === "string" && item.name !== "") return item.name;

    return "#" + (index + 1);
  }

  // renderMap handles both a free-form map (sessions[].env) and one whose
  // key column is a closed choice (keybindings, via mapKeyOptions) — an
  // action id typo is exactly the class of mistake this editor exists to
  // make impossible.
  function renderMap(field, prop, container, state, tab) {
    const wrap = el("div", "cfg-field cfg-list");
    wrap.appendChild(el("div", "cfg-field-head", el("code", null, prop)));

    const help = field["help_" + lang] || field.help_en;
    if (help) wrap.appendChild(el("p", "cfg-help", stripInlineMarkup(help)));

    if (!state[prop] || typeof state[prop] !== "object") state[prop] = {};
    const map = state[prop];

    const rows = el("div", "cfg-list-rows");
    wrap.appendChild(rows);

    for (const key of Object.keys(map)) {
      rows.appendChild(renderMapRow(field, map, key, tab));
    }

    const addRow = el("div", "cfg-list-row cfg-map-add");
    const keyInput = field.mapKeyOptions ? buildMapKeySelect(field, map) : buildPlainInput(t("key"));
    const valueInput = buildPlainInput(t("value"));
    const addBtn = el("button", "btn cfg-add", "+ " + t("add"));
    addBtn.type = "button";
    addBtn.addEventListener("click", () => {
      const key = keyInput.value.trim();
      if (key === "") return;

      map[key] = valueInput.value;
      tab.rebuild();
    });

    addRow.appendChild(keyInput);
    addRow.appendChild(valueInput);
    addRow.appendChild(addBtn);
    wrap.appendChild(addRow);

    container.appendChild(wrap);
  }

  function buildPlainInput(placeholder) {
    const input = document.createElement("input");
    input.type = "text";
    input.placeholder = placeholder;

    return input;
  }

  function buildMapKeySelect(field, map) {
    const select = document.createElement("select");
    for (const id of field.mapKeyOptions) {
      if (map[id] !== undefined) continue; // already mapped — one row per action id

      const opt = document.createElement("option");
      opt.value = id;
      opt.textContent = id;
      select.appendChild(opt);
    }

    return select;
  }

  function renderMapRow(field, map, key, tab) {
    const row = el("div", "cfg-list-row");

    row.appendChild(el("code", "cfg-map-key", key));

    const valueInput = document.createElement("input");
    valueInput.type = "text";
    valueInput.value = map[key];
    valueInput.addEventListener("input", () => {
      map[key] = valueInput.value;
      tab.update();
    });
    row.appendChild(valueInput);

    const removeBtn = el("button", "btn cfg-remove", "✕");
    removeBtn.type = "button";
    removeBtn.addEventListener("click", () => {
      delete map[key];
      tab.rebuild();
    });
    row.appendChild(removeBtn);

    return row;
  }

  // ---------- YAML serialization (form -> right panel) ----------

  function updateYAML(tabName, tab) {
    const lines = [];
    serializeChildren(tab.tree, tab.state, 0, lines, tab.isConfig);

    const out = document.getElementById("yaml-" + tabName);
    if (out) out.textContent = lines.length ? lines.join("\n") : "# " + emptyComment(tabName);
  }

  function emptyComment(tabName) {
    if (lang === "fr") {
      return tabName === "config" ? "Rien ne diffère des valeurs par défaut." : "Aucun champ renseigné.";
    }

    return tabName === "config" ? "Nothing differs from the defaults." : "Nothing filled in yet.";
  }

  function serializeChildren(node, state, indent, lines, isConfig) {
    for (const prop in node.children) {
      serializeNode(node.children[prop], prop, state ? state[prop] : undefined, indent, lines, isConfig);
    }
  }

  function serializeNode(field, key, value, indent, lines, isConfig) {
    const pad = "  ".repeat(indent);

    switch (field.type) {
      case "group": {
        const inner = [];
        serializeChildren(field, value || {}, indent + 1, inner, isConfig);
        if (inner.length === 0) return;

        lines.push(pad + key + ":");
        for (const l of inner) lines.push(l);

        break;
      }

      case "list": {
        if (!Array.isArray(value) || value.length === 0) return;

        lines.push(pad + key + ":");
        for (const item of value) {
          if (field.itemType === "struct") {
            const inner = [];
            serializeChildren(field, item || {}, indent + 2, inner, isConfig);

            if (inner.length === 0) {
              lines.push(pad + "  - {}");

              continue;
            }

            lines.push(pad + "  - " + inner[0].replace(/^\s+/, ""));
            for (let i = 1; i < inner.length; i++) lines.push(inner[i]);
          } else {
            lines.push(pad + "  - " + scalarYAML(item));
          }
        }

        break;
      }

      case "map": {
        if (!value || Object.keys(value).length === 0) return;

        lines.push(pad + key + ":");
        for (const k of Object.keys(value)) {
          lines.push(pad + "  " + scalarYAML(k) + ": " + scalarYAML(value[k]));
        }

        break;
      }

      default: {
        if (isConfig) {
          if (value === undefined || value === field.default) return;
        } else if (isEmptyScalar(value)) {
          return;
        }

        lines.push(pad + key + ": " + scalarYAML(value));
      }
    }
  }

  function isEmptyScalar(v) {
    return v === undefined || v === null || v === "";
  }

  function scalarYAML(v) {
    if (typeof v === "boolean") return v ? "true" : "false";
    if (typeof v === "number") return String(v);
    if (v === null || v === undefined) return "null";

    const s = String(v);
    if (s === "" || needsQuote(s)) return JSON.stringify(s);

    return s;
  }

  function needsQuote(s) {
    if (/^\s|\s$/.test(s)) return true;
    if (/^[-?:,\[\]{}#&*!|>'"%@`]/.test(s)) return true;
    if (/:\s|\s#/.test(s)) return true;
    if (/^(true|false|null|yes|no|~)$/i.test(s)) return true;
    if (/^-?\d+(\.\d+)?$/.test(s)) return true;

    return false;
  }

  // ---------- minimal YAML parser (paste -> form) ----------
  //
  // Not a general YAML parser: just enough of the subset config.yml and
  // lazyshell.yml actually use (mappings, block sequences, both sequence
  // shapes — "- item" and "- key: value" — scalars, quoting, comments) to
  // read back what the serializer above, or `lazyshell config init`,
  // produces. Given that, it is deliberately not defensive about the rest
  // of YAML's grammar (anchors, multi-line strings, flow collections):
  // anything it cannot make sense of degrades to an unrecognized key,
  // reported the same way an actually unknown key is.

  function parseYAML(text) {
    const entries = [];

    for (const raw of text.split("\n")) {
      const stripped = stripComment(raw.replace(/\r$/, ""));
      if (stripped.trim() === "") continue;

      entries.push({ indent: indentOf(stripped), text: stripped.trim() });
    }

    let pos = 0;

    function parseBlock(indent) {
      if (pos >= entries.length || entries[pos].indent < indent) return {};

      if (isSeqEntry(entries[pos].text)) return parseSequence(indent);

      return parseMapping(indent);
    }

    function isSeqEntry(s) {
      return s === "-" || s.indexOf("- ") === 0;
    }

    function parseSequence(indent) {
      const arr = [];

      while (pos < entries.length && entries[pos].indent === indent && isSeqEntry(entries[pos].text)) {
        const entry = entries[pos];
        const rest = entry.text === "-" ? "" : entry.text.slice(2);

        if (rest === "") {
          pos++;
          const nextIndent = pos < entries.length ? entries[pos].indent : indent + 2;
          arr.push(nextIndent > indent ? parseBlock(nextIndent) : null);

          continue;
        }

        const m = rest.match(/^([^:]+):(\s*(.*))?$/);
        if (m) {
          // "- key: value" is the first key of a mapping item — rewrite this
          // entry in place as a plain mapping key at a synthetic indent one
          // level past the dash, then let parseMapping read it (and
          // whatever follows at that same indent) normally.
          const virtualIndent = entry.indent + 2;
          entries[pos] = { indent: virtualIndent, text: rest };
          arr.push(parseMapping(virtualIndent));

          continue;
        }

        pos++;
        arr.push(parseScalar(rest));
      }

      return arr;
    }

    function parseMapping(indent) {
      const obj = {};

      while (pos < entries.length && entries[pos].indent === indent && !isSeqEntry(entries[pos].text)) {
        const entry = entries[pos];
        const m = entry.text.match(/^([^:]+):(\s*(.*))?$/);

        if (!m) {
          pos++;

          continue;
        }

        const key = unquoteKey(m[1].trim());
        const rawVal = (m[3] || "").trim();
        pos++;

        if (rawVal === "") {
          if (pos < entries.length && entries[pos].indent > indent) {
            obj[key] = parseBlock(entries[pos].indent);
          } else {
            obj[key] = null;
          }
        } else {
          obj[key] = parseScalar(rawVal);
        }
      }

      return obj;
    }

    return parseBlock(0);
  }

  function stripComment(line) {
    let inS = false;
    let inD = false;

    for (let i = 0; i < line.length; i++) {
      const c = line[i];

      if (c === "'" && !inD) inS = !inS;
      else if (c === '"' && !inS) inD = !inD;
      else if (c === "#" && !inS && !inD && (i === 0 || /\s/.test(line[i - 1]))) return line.slice(0, i);
    }

    return line;
  }

  function indentOf(line) {
    const m = line.match(/^ */);

    return m[0].length;
  }

  function unquoteKey(s) {
    if (s.length >= 2 && s[0] === '"' && s[s.length - 1] === '"') {
      try {
        return JSON.parse(s);
      } catch {
        return s.slice(1, -1);
      }
    }

    if (s.length >= 2 && s[0] === "'" && s[s.length - 1] === "'") return s.slice(1, -1).replace(/''/g, "'");

    return s;
  }

  function parseScalar(raw) {
    const s = raw.trim();

    if (s === "") return "";
    if (s === "{}" || s === "[]") return s === "{}" ? {} : [];

    if (s.length >= 2 && s[0] === '"' && s[s.length - 1] === '"') {
      try {
        return JSON.parse(s);
      } catch {
        return s.slice(1, -1);
      }
    }

    if (s.length >= 2 && s[0] === "'" && s[s.length - 1] === "'") return s.slice(1, -1).replace(/''/g, "'");

    if (s === "true") return true;
    if (s === "false") return false;
    if (s === "null" || s === "~") return null;
    if (/^-?\d+$/.test(s)) return parseInt(s, 10);

    return s;
  }

  // ---------- applying a parsed document onto the form's state ----------

  function wireApply(tabName, tab) {
    const btn = document.getElementById("apply-" + tabName);
    const textarea = document.getElementById("paste-" + tabName);
    const warningsBox = document.getElementById("warnings-" + tabName);
    if (!btn || !textarea) return;

    btn.addEventListener("click", () => {
      const parsed = parseYAML(textarea.value);
      const warnings = [];

      if (typeof parsed !== "object" || Array.isArray(parsed) || parsed === null) {
        renderWarnings(warningsBox, [t("notMapping")]);

        return;
      }

      const newState = {};
      applyParsed(tab.tree, parsed, newState, "", warnings);

      tab.state = newState;
      tab.rebuild();
      renderWarnings(warningsBox, warnings);
    });
  }

  function applyParsed(node, parsed, state, path, warnings) {
    for (const key of Object.keys(parsed)) {
      const field = node.children[key];
      const here = path ? path + "." + key : key;

      if (!field) {
        warnings.push(here);

        continue;
      }

      applyValue(field, key, parsed[key], state, here, warnings);
    }
  }

  function applyValue(field, key, value, state, path, warnings) {
    switch (field.type) {
      case "group":
        if (value && typeof value === "object" && !Array.isArray(value)) {
          state[key] = {};
          applyParsed(field, value, state[key], path, warnings);
        }

        break;

      case "list":
        if (!Array.isArray(value)) break;

        if (field.itemType === "struct") {
          state[key] = value.map((item) => {
            const sub = {};
            if (item && typeof item === "object") applyParsed(field, item, sub, path + "[]", warnings);

            return sub;
          });
        } else {
          state[key] = value.map((v) => String(v));
        }

        break;

      case "map":
        if (value && typeof value === "object" && !Array.isArray(value)) {
          state[key] = {};
          for (const k of Object.keys(value)) {
            if (field.mapKeyOptions && field.mapKeyOptions.indexOf(k) === -1) {
              warnings.push(path + "." + k);

              continue;
            }

            state[key][k] = String(value[k]);
          }
        }

        break;

      case "enum":
        if (field.enum && field.enum.indexOf(value) === -1) {
          warnings.push(path + " = " + JSON.stringify(value));
        } else {
          state[key] = value;
        }

        break;

      case "int":
        state[key] = typeof value === "number" ? value : parseInt(value, 10);
        break;

      default:
        state[key] = value;
    }
  }

  function renderWarnings(box, warnings) {
    if (!box) return;

    box.textContent = "";
    if (!warnings || warnings.length === 0) return;

    const title = el("p", "cfg-warnings-title", t("warningsTitle"));
    box.appendChild(title);

    const list = el("ul", null);
    for (const w of warnings) list.appendChild(el("li", null, w));
    box.appendChild(list);
  }

  // ---------- copy button ----------

  function wireCopy(tabName) {
    const btn = document.getElementById("copy-" + tabName);
    const out = document.getElementById("yaml-" + tabName);
    if (!btn || !out) return;

    btn.addEventListener("click", () => {
      const text = out.textContent;
      const original = btn.textContent;

      const done = () => {
        btn.textContent = t("copied");
        setTimeout(() => {
          btn.textContent = original;
        }, 1200);
      };

      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, done);

        return;
      }

      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try {
        document.execCommand("copy");
      } catch {
        /* best effort — nothing better available */
      }
      document.body.removeChild(ta);
      done();
    });
  }

  // ---------- small DOM/text helpers ----------

  function el(tag, className, content) {
    const node = document.createElement(tag);
    if (className) node.className = className;

    if (content instanceof Node) node.appendChild(content);
    else if (content !== undefined && content !== null) node.textContent = content;

    return node;
  }

  function humanLabel(key) {
    return key.replace(/_/g, " ").replace(/^./, (c) => c.toUpperCase());
  }

  // stripInlineMarkup drops the README's markdown-isms (backtick code,
  // links) from help text shown in a plain <p> — keeping the words, not the
  // syntax meant for a markdown renderer this page does not have.
  function stripInlineMarkup(s) {
    return s
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      .replace(/`/g, "");
  }
})();
